mapper.insert:
insert into research_project_member(project_id,user_id,member_role,responsibility,allocation_percent,join_date,status,create_by)
select #{projectId},user_id,
  case when member_role='PI' then 'PI' else member_role end,responsibility,planned_allocation,curdate(),'ACTIVE',#{username}
from research_proposal_member where proposal_id=#{proposalId}

mapper.update:
update research_project

  current_planned_end_date=#{plannedEndDate},
  current_budget=#{currentBudget},
  project_name=#{projectName},
  version=version+1,update_by=#{username}

where project_id=#{projectId}

mapper.select:
select p.status name,count(*) value from research_proposal p
p.applicant_user_id=#{userId}
group by p.status
